package forth

import (
	"errors"
	"strconv"
	"strings"
)

var (
	errEmptyStack   = errors.New("empty stack")
	errOneValue     = errors.New("only one value on the stack")
	errDivideByZero = errors.New("divide by zero")
	errUndefined    = errors.New("undefined operation")
	errIllegal      = errors.New("illegal operation")
)

// op is a single executable Forth operation.
type op func(*vm) error

// vm holds the data stack and the dictionary of user-defined words.
type vm struct {
	stack []int
	defs  map[string][]op
}

// Forth evaluates the given lines of Forth and returns the resulting stack.
func Forth(input []string) ([]int, error) {
	v := &vm{
		stack: []int{},
		defs:  map[string][]op{},
	}
	for _, line := range input {
		tokens := strings.Fields(line)
		if len(tokens) == 0 {
			continue
		}
		if tokens[0] == ":" {
			if err := v.define(tokens); err != nil {
				return nil, err
			}
			continue
		}
		for _, tok := range tokens {
			if isNumber(tok) {
				n, err := strconv.Atoi(tok)
				if err != nil {
					return nil, err
				}
				if err := v.push(n); err != nil {
					return nil, err
				}
				continue
			}
			o, err := v.resolveWord(strings.ToLower(tok))
			if err != nil {
				return nil, err
			}
			if err := o(v); err != nil {
				return nil, err
			}
		}
	}
	return v.stack, nil
}

// define processes a ": name body ;" definition line.
// The body is resolved against the current dictionary before the new
// definition is installed, so words referenced in the body capture their
// definitions as they exist at the time the word is defined.
func (v *vm) define(tokens []string) error {
	if len(tokens) < 3 {
		return errIllegal
	}
	name := strings.ToLower(tokens[1])
	if isNumber(name) {
		return errIllegal
	}
	end := -1
	for i := 2; i < len(tokens); i++ {
		if tokens[i] == ";" {
			end = i
			break
		}
	}
	if end == -1 {
		return errIllegal
	}
	body := make([]op, 0, end-2)
	for _, tok := range tokens[2:end] {
		if isNumber(tok) {
			n, err := strconv.Atoi(tok)
			if err != nil {
				return errIllegal
			}
			n := n
			body = append(body, func(m *vm) error { return m.push(n) })
			continue
		}
		o, err := v.resolveWord(strings.ToLower(tok))
		if err != nil {
			return err
		}
		body = append(body, o)
	}
	v.defs[name] = body
	return nil
}

// resolveWord looks up a word in the user dictionary first, then among the
// built-in words.
func (v *vm) resolveWord(w string) (op, error) {
	if def, ok := v.defs[w]; ok {
		return func(m *vm) error {
			for _, o := range def {
				if err := o(m); err != nil {
					return err
				}
			}
			return nil
		}, nil
	}
	if b, ok := builtinWords[w]; ok {
		return b, nil
	}
	return nil, errUndefined
}

// isNumber reports whether s is a (possibly negative) integer literal.
func isNumber(s string) bool {
	if s == "" {
		return false
	}
	start := 0
	if s[0] == '-' {
		if len(s) == 1 {
			return false
		}
		start = 1
	}
	for i := start; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func (v *vm) push(x int) error {
	v.stack = append(v.stack, x)
	return nil
}

func (v *vm) pop() (int, error) {
	if len(v.stack) == 0 {
		return 0, errEmptyStack
	}
	n := len(v.stack)
	x := v.stack[n-1]
	v.stack = v.stack[:n-1]
	return x, nil
}

func (v *vm) pop2() (a, b int, err error) {
	if len(v.stack) == 0 {
		return 0, 0, errEmptyStack
	}
	if len(v.stack) == 1 {
		return 0, 0, errOneValue
	}
	n := len(v.stack)
	b = v.stack[n-1]
	a = v.stack[n-2]
	v.stack = v.stack[:n-2]
	return a, b, nil
}

func add(v *vm) error {
	b, a, err := v.pop2()
	if err != nil {
		return err
	}
	return v.push(a + b)
}

func sub(v *vm) error {
	b, a, err := v.pop2()
	if err != nil {
		return err
	}
	return v.push(a - b)
}

func mul(v *vm) error {
	b, a, err := v.pop2()
	if err != nil {
		return err
	}
	return v.push(a * b)
}

func div(v *vm) error {
	b, a, err := v.pop2()
	if err != nil {
		return err
	}
	if b == 0 {
		return errDivideByZero
	}
	return v.push(a / b)
}

func dup(v *vm) error {
	if len(v.stack) == 0 {
		return errEmptyStack
	}
	n := len(v.stack)
	return v.push(v.stack[n-1])
}

func drop(v *vm) error {
	if len(v.stack) == 0 {
		return errEmptyStack
	}
	v.stack = v.stack[:len(v.stack)-1]
	return nil
}

func swap(v *vm) error {
	if len(v.stack) == 0 {
		return errEmptyStack
	}
	if len(v.stack) == 1 {
		return errOneValue
	}
	n := len(v.stack)
	v.stack[n-1], v.stack[n-2] = v.stack[n-2], v.stack[n-1]
	return nil
}

func over(v *vm) error {
	if len(v.stack) == 0 {
		return errEmptyStack
	}
	if len(v.stack) == 1 {
		return errOneValue
	}
	n := len(v.stack)
	return v.push(v.stack[n-2])
}

var builtinWords = map[string]op{
	"+":    add,
	"-":    sub
	"*":    mul,
	"/":    div,
	"dup":  dup,
	"drop": drop,
	"swap": swap,
	"over": over,
}

